# Four-channel reflection/projection with cyclic n+1 handoff.
# GNU as, Linux x86-64. No input files or external dependencies.
# stdout: 8 little-endian uint64 words per execution; 8 executions/cycle.
# Reflection order 1,2,3,4; projection destination order 2,3,4,1.
.equ CYCLES, 100
.section .data
.balign 8
phase:
.quad 1,14682301134823862838,2,1
feedback1:
.quad 1,0,163,139585200436464062,10313243124162931083,8289073189891983783,1,51628
feedback2:
.quad 1,5,1,12987477425939165642,13897417997859886758,14682301134823862837,14682301134823862838,64822
feedback3:
.quad 1,14,94,15887544411260482880,7283792525027352111,1890352290247067121,2,74709
feedback4:
.quad 1,4,1,4683748157146820982,1456000778129704969,16825472496404509834,1,69305
.section .bss
.balign 8
state: .skip 8
relations: .skip 8
constraints: .skip 8
observations: .skip 8
unresolved: .skip 8
context: .skip 8
target: .skip 8
events: .skip 8
reflected1: .skip 64
reflected2: .skip 64
reflected3: .skip 64
reflected4: .skip 64
.section .text
.globl _start
.type _start,@function
_start:
movq $CYCLES, %r12
cycle_loop:
# Reflect channel 1; phase overwrites the first four cells.
leaq feedback1(%rip), %rsi
leaq state(%rip), %rdi
movq $8, %rcx
rep movsq
movq phase+0(%rip), %rax
movq %rax, state(%rip)
movq phase+8(%rip), %rax
movq %rax, relations(%rip)
movq phase+16(%rip), %rax
movq %rax, constraints(%rip)
movq phase+24(%rip), %rax
movq %rax, observations(%rip)
call reflect_channel1
leaq state(%rip), %rsi
leaq reflected1(%rip), %rdi
movq $8, %rcx
rep movsq
call emit_registers
# Reflect channel 2; phase overwrites the first four cells.
leaq feedback2(%rip), %rsi
leaq state(%rip), %rdi
movq $8, %rcx
rep movsq
movq phase+0(%rip), %rax
movq %rax, state(%rip)
movq phase+8(%rip), %rax
movq %rax, relations(%rip)
movq phase+16(%rip), %rax
movq %rax, constraints(%rip)
movq phase+24(%rip), %rax
movq %rax, observations(%rip)
call reflect_channel2
leaq state(%rip), %rsi
leaq reflected2(%rip), %rdi
movq $8, %rcx
rep movsq
call emit_registers
# Reflect channel 3; phase overwrites the first four cells.
leaq feedback3(%rip), %rsi
leaq state(%rip), %rdi
movq $8, %rcx
rep movsq
movq phase+0(%rip), %rax
movq %rax, state(%rip)
movq phase+8(%rip), %rax
movq %rax, relations(%rip)
movq phase+16(%rip), %rax
movq %rax, constraints(%rip)
movq phase+24(%rip), %rax
movq %rax, observations(%rip)
call reflect_channel3
leaq state(%rip), %rsi
leaq reflected3(%rip), %rdi
movq $8, %rcx
rep movsq
call emit_registers
# Reflect channel 4; phase overwrites the first four cells.
leaq feedback4(%rip), %rsi
leaq state(%rip), %rdi
movq $8, %rcx
rep movsq
movq phase+0(%rip), %rax
movq %rax, state(%rip)
movq phase+8(%rip), %rax
movq %rax, relations(%rip)
movq phase+16(%rip), %rax
movq %rax, constraints(%rip)
movq phase+24(%rip), %rax
movq %rax, observations(%rip)
call reflect_channel4
leaq state(%rip), %rsi
leaq reflected4(%rip), %rdi
movq $8, %rcx
rep movsq
call emit_registers
# Turn 1 -> 2: preserve all cells except state <- target.
leaq reflected1(%rip), %rsi
leaq state(%rip), %rdi
movq $8, %rcx
rep movsq
movq target(%rip), %rax
movq %rax, state(%rip)
call project_channel2
leaq state(%rip), %rsi
leaq feedback2(%rip), %rdi
movq $8, %rcx
rep movsq
call emit_registers
# Turn 2 -> 3: preserve all cells except state <- target.
leaq reflected2(%rip), %rsi
leaq state(%rip), %rdi
movq $8, %rcx
rep movsq
movq target(%rip), %rax
movq %rax, state(%rip)
call project_channel3
leaq state(%rip), %rsi
leaq feedback3(%rip), %rdi
movq $8, %rcx
rep movsq
call emit_registers
# Turn 3 -> 4: preserve all cells except state <- target.
leaq reflected3(%rip), %rsi
leaq state(%rip), %rdi
movq $8, %rcx
rep movsq
movq target(%rip), %rax
movq %rax, state(%rip)
call project_channel4
leaq state(%rip), %rsi
leaq feedback4(%rip), %rdi
movq $8, %rcx
rep movsq
call emit_registers
# Turn 4 -> 1: preserve all cells except state <- target.
leaq reflected4(%rip), %rsi
leaq state(%rip), %rdi
movq $8, %rcx
rep movsq
movq target(%rip), %rax
movq %rax, state(%rip)
call project_channel1
leaq state(%rip), %rsi
leaq feedback1(%rip), %rdi
movq $8, %rcx
rep movsq
call emit_registers
movq feedback1+48(%rip), %rax
movq %rax, phase+0(%rip)
movq feedback2+48(%rip), %rax
movq %rax, phase+8(%rip)
movq feedback3+48(%rip), %rax
movq %rax, phase+16(%rip)
movq feedback4+48(%rip), %rax
movq %rax, phase+24(%rip)
decq %r12
jnz cycle_loop
movq $60, %rax
xorq %rdi, %rdi
syscall
emit_registers:
leaq state(%rip), %rsi
movq $64, %rdx
emit_more:
movq $1, %rax
movq $1, %rdi
syscall
cmpq $-4, %rax
je emit_more
testq %rax, %rax
jle output_failed
addq %rax, %rsi
subq %rax, %rdx
jnz emit_more
ret
output_failed:
movq $60, %rax
movq $1, %rdi
syscall
